BEGIN;
SELECT plan(16);
SELECT has_table('public','exam_result_sets','result sets table exists');
SELECT has_table('public','exam_student_results','student results table exists');
SELECT col_is_null('public','exam_student_results','result_indicator','indicator is optional');
SELECT col_is_null('public','exam_student_results','result_comment','comment is optional');
SELECT col_is_null('public','exam_student_results','follow_up_status','follow-up is optional');
SELECT policies_are('public','exam_result_sets',ARRAY['exam_result_sets_admin_insert','exam_result_sets_admin_select','exam_result_sets_admin_update','exam_result_sets_parent_select','exam_result_sets_student_select'],'result set RLS policies');
SELECT policies_are('public','exam_student_results',ARRAY['exam_student_results_admin_delete','exam_student_results_admin_insert','exam_student_results_admin_select','exam_student_results_admin_update','exam_student_results_parent_select','exam_student_results_student_select'],'student result RLS policies');
SELECT has_index('public','exam_result_sets','exam_result_sets_one_draft_idx','one draft per event');
SELECT has_index('public','exam_result_sets','exam_result_sets_one_published_idx','one active publication per event');
SELECT has_function('public','save_exam_result_draft',ARRAY['uuid','numeric','jsonb','text'],'draft RPC exists');
SELECT has_function('public','publish_exam_result',ARRAY['uuid'],'publish RPC exists');
SELECT function_privs_are('public','save_exam_result_draft',ARRAY['uuid','numeric','jsonb','text'],'anon',ARRAY[]::text[],'anonymous cannot save');
SELECT function_privs_are('public','publish_exam_result',ARRAY['uuid'],'anon',ARRAY[]::text[],'anonymous cannot publish');
SELECT throws_ok($$INSERT INTO public.exam_student_results(id,institute_id,exam_result_set_id,student_id,student_assignment_id,marks_obtained,result_indicator,follow_up_status) VALUES(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),0,'excellent','pending')$$,'23514',NULL,'follow-up only allowed for parent call');
SELECT throws_ok($$INSERT INTO public.exam_result_sets(institute_id,schedule_event_id,academic_year_id,batch_id,version_no,max_marks,status,created_by) VALUES(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),1,0,'draft',gen_random_uuid())$$,'23514',NULL,'maximum marks must be positive');
SELECT throws_ok($$INSERT INTO public.exam_student_results(id,institute_id,exam_result_set_id,student_id,student_assignment_id,marks_obtained) VALUES(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),-1)$$,'23514',NULL,'marks must be non-negative');
SELECT * FROM finish();
ROLLBACK;
